}

.card {
  background: #ffffff;
  border-radius: 16px;
  padding: 40px 44px;
  box-shadow: 0 4px 24px rgba(0, 0, 0, 0.08), 0 1px 4px rgba(0, 0, 0, 0.04);
}

.card-header {
  margin-bottom: 32px;
}

.card-header h1 {
  font-size: 22px;
  font-weight: 700;
  color: #0f172a;
  letter-spacing: -0.3px;
}

.card-header p {
  margin-top: 6px;
  font-size: 14px;
  color: #64748b;
  line-height: 1.5;
}

/* form-field wrapper */
.form-field {
  margin-bottom: 32px;
}

.form-field legend {
  font-size: 15px;
  font-weight: 600;
  color: #0f172a;
  margin-bottom: 16px;
  display: block;
}

/* Radio options */
.radio-group {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.radio-option {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 16px;
  border: 1.5px solid #e2e8f0;
  border-radius: 10px;
  cursor: pointer;
  transition: border-color 0.15s ease, background 0.15s ease, box-shadow 0.15s ease;
  user-select: none;
}

.radio-option:hover {
  border-color: #6366f1;
  background: #f5f3ff;
}

.radio-option input[type="radio"] {
  appearance: none;
  -webkit-appearance: none;
  width: 18px;
  height: 18px;
  border: 2px solid #cbd5e1;
  border-radius: 50%;
  flex-shrink: 0;
  transition: border-color 0.15s ease;
  position: relative;
  cursor: pointer;
}

.radio-option input[type="radio"]:focus-visible {
  outline: 2px solid #6366f1;
  outline-offset: 2px;
}

.radio-option input[type="radio"]:checked {
  border-color: #6366f1;
  border-width: 5px;
  background: #ffffff;
}

.radio-option:has(input[type="radio"]:checked) {
  border-color: #6366f1;
  background: #f5f3ff;
  box-shadow: 0 0 0 1px #6366f1 inset;
}

.radio-label {
  font-size: 15px;
  font-weight: 500;
  color: #334155;
  cursor: pointer;
}

.radio-option:has(input[type="radio"]:checked) .radio-label {
  color: #4338ca;
}

/* Option icons */
.option-icon {
  margin-left: auto;
  font-size: 18px;
  opacity: 0.55;
  transition: opacity 0.15s;
}

.radio-option:has(input[type="radio"]:checked) .option-icon {
  opacity: 1;
}

/* Submit button */
.btn-submit {
  width: 100%;
  padding: 14px;
  background: #6366f1;
  color: #ffffff;
  font-size: 15px;
  font-weight: 600;
  border: none;
  border-radius: 10px;
  cursor: pointer;
  letter-spacing: 0.1px;
  transition: background 0.15s ease, transform 0.1s ease, box-shadow 0.15s ease;
  box-shadow: 0 2px 8px rgba(99, 102, 241, 0.35);
}

.btn-submit:hover {
  background: #4f46e5;
  box-shadow: 0 4px 16px rgba(99, 102, 241, 0.45);
}

.btn-submit:active {
  transform: translateY(1px);
  box-shadow: 0 1px 4px rgba(99, 102, 241, 0.3);
}

.btn-submit:focus-visible {
  outline: 2px solid #6366f1;
  outline-offset: 3px;
}

.btn-submit:disabled {
  background: #c7d2fe;
  box-shadow: none;
  cursor: not-allowed;
  transform: none;
