  align-items: center;
  gap: 10px;
  margin-top: 20px;
  padding: 14px 16px;
  background: #f0fdf4;
  border: 1.5px solid #86efac;
  border-radius: 10px;
  font-size: 14px;
  font-weight: 500;
  color: #166534;
}

.success-banner.visible {
  display: flex;
}

.success-icon {
  font-size: 18px;
