+// ------------------------------------------------------------
+// Minimal React-style component system (no build step needed)
+// ------------------------------------------------------------
+
+function createElement(tag, props, ...children) {
+  const el = document.createElement(tag);
+
+  if (props) {
+    Object.entries(props).forEach(([key, value]) => {
+      if (key === "className") {
+        el.className = value;
+      } else if (key === "htmlFor") {
+        el.setAttribute("for", value);
+      } else if (key.startsWith("on") && typeof value === "function") {
+        el.addEventListener(key.slice(2).toLowerCase(), value);
+      } else if (key === "checked") {
+        el.checked = value;
+      } else if (key === "disabled") {
+        el.disabled = value;
+      } else {
+        el.setAttribute(key, value);
+      }
+    });
+  }
+
+  children.flat(Infinity).forEach((child) => {
+    if (child == null || child === false) return;
+    el.appendChild(
+      typeof child === "string" || typeof child === "number"
+        ? document.createTextNode(String(child))
+        : child
+    );
+  });
+
+  return el;
+}
+
+// ------------------------------------------------------------
+// State
+// ------------------------------------------------------------
+
+const state = {
+  selected: null,
+  submitted: false,
+};
+
+const notificationOptions = [
+  { id: "email",  label: "Email",              icon: "✉️" },
+  { id: "sms",    label: "SMS",                icon: "💬" },
+  { id: "push",   label: "Push Notifications", icon: "🔔" },
+];
+
+// ------------------------------------------------------------
+// Components
+// ------------------------------------------------------------
+
+function RadioOption({ option, isSelected, onChange }) {
+  const input = createElement("input", {
+    type: "radio",
+    id: `notif-${option.id}`,
+    name: "notification",
+    value: option.id,
+    checked: isSelected,
+    onChange,
+  });
+
+  // Keep checked state in sync since we're manually re-rendering
+  input.checked = isSelected;
+
+  const label = createElement(
+    "label",
+    { className: "radio-label", htmlFor: `notif-${option.id}` },
+    option.label
+  );
+
+  const icon = createElement("span", { className: "option-icon", "aria-hidden": "true" }, option.icon);
+
+  return createElement(
+    "div",
+    { className: "radio-option" },
+    input,
+    label,
+    icon
+  );
+}
+
+function FormField({ selected, onSelect }) {
+  const legend = createElement(
+    "legend",
+    null,
+    "How do you prefer to receive notifications?"
+  );
+
+  const radioGroup = createElement("div", { className: "radio-group", role: "group" });
+
+  notificationOptions.forEach((option) => {
+    const optionEl = RadioOption({
+      option,
+      isSelected: selected === option.id,
+      onChange: () => onSelect(option.id),
+    });
+    radioGroup.appendChild(optionEl);
+  });
+
+  return createElement(
+    "div",
+    { className: "form-field" },
+    createElement("fieldset", { style: "border:none;padding:0;margin:0;" }, legend, radioGroup)
+  );
+}
+
+function SuccessBanner({ visible, selected }) {
+  const option = notificationOptions.find((o) => o.id === selected);
+  const banner = createElement(
+    "div",
+    { className: `success-banner${visible ? " visible" : ""}`, role: "status", "aria-live": "polite" },
+    createElement("span", { className: "success-icon", "aria-hidden": "true" }, "✅"),
+    `Preference saved! You'll receive notifications via ${option ? option.label : ""}.`
+  );
+  return banner;
+}
+
+function App() {
+  let currentSelected = state.selected;
+  let currentSubmitted = state.submitted;
+
+  function handleSelect(id) {
+    state.selected = id;
+    state.submitted = false;
+    render();
+  }
+
+  function handleSubmit(e) {
+    e.preventDefault();
+    if (!state.selected) return;
+    state.submitted = true;
+    render();
+  }
+
+  const header = createElement(
+    "div",
+    { className: "card-header" },
+    createElement("h1", null, "Notification Preferences"),
+    createElement("p", null, "Choose how you'd like to stay up to date.")
+  );
+
+  const formField = FormField({ selected: currentSelected, onSelect: handleSelect });
+
+  const submitBtn = createElement(
+    "button",
+    {
+      type: "submit",
+      className: "btn-submit",
+      disabled: !currentSelected || undefined,
+    },
+    "Save Preference"
+  );
+  if (!currentSelected) submitBtn.disabled = true;
+
+  const form = createElement("form", { onSubmit: handleSubmit }, formField, submitBtn);
+
+  const successBanner = SuccessBanner({ visible: currentSubmitted, selected: currentSelected });
+
+  const card = createElement("div", { className: "card" }, header, form, successBanner);
+  const page = createElement("div", { className: "page" }, card);
+
+  return page;
+}
